import HTMLIngredient from "../../src/web/HTMLIngredient.mjs";

/**
 * Builds a deterministic fake App. Each call to nextIngId() increments a
 * per-test counter so ingredient ids can be asserted exactly.
 */
function makeApp() {
    let next = 0;
    return {
        nextIngId: jest.fn(() => ++next)
    };
}

function makeManager() {
    return {
        addDynamicListener: jest.fn(),
        recipe: {
            ingChange: jest.fn()
        }
    };
}

function makeIngredient(config, overrides = {}) {
    const app = overrides.app || makeApp();
    const manager = overrides.manager || makeManager();
    const ingredient = new HTMLIngredient({
        name: "Arg",
        type: "string",
        value: "",
        ...config
    }, app, manager);
    return {ingredient, app, manager};
}

function parseHtml(html) {
    const container = document.createElement("div");
    container.innerHTML = html;
    return container;
}

describe("HTMLIngredient constructor", () => {
    test("derives id and tab index from the App ingredient counter", () => {
        const app = {nextIngId: jest.fn(() => 7)};
        const ingredient = new HTMLIngredient({name: "A", type: "string", value: "v"}, app, makeManager());

        expect(app.nextIngId).toHaveBeenCalledTimes(1);
        expect(ingredient.ingId).toBe(7);
        expect(ingredient.id).toBe("ing-7");
        expect(ingredient.tabIndex).toBe(9); // Input = 1, Search = 2, then ingredient id
    });

    test("applies documented defaults when optional config is omitted", () => {
        const {ingredient} = makeIngredient({name: "A", type: "string", value: "v"});

        expect(ingredient.name).toBe("A");
        expect(ingredient.type).toBe("string");
        expect(ingredient.value).toBe("v");
        expect(ingredient.disabled).toBe(false);
        expect(ingredient.hint).toBe(false);
        expect(ingredient.rows).toBe(false);
        expect(ingredient.target).toBeUndefined();
        expect(ingredient.defaultIndex).toBe(0);
        expect(ingredient.maxLength).toBeNull();
        expect(ingredient.toggleValues).toBeUndefined();
        expect(ingredient.min).toBe("");
        expect(ingredient.max).toBe("");
        expect(ingredient.step).toBe(1);
    });

    test("preserves explicit config values, including numeric boundaries", () => {
        const {ingredient} = makeIngredient({
            name: "Num",
            type: "number",
            value: 5,
            disabled: true,
            hint: "A hint",
            rows: 4,
            target: [1, 2],
            defaultIndex: 3,
            maxLength: 12,
            toggleValues: ["Hex", "Decimal"],
            min: -10,
            max: 0,
            step: 0.5
        });

        expect(ingredient.disabled).toBe(true);
        expect(ingredient.hint).toBe("A hint");
        expect(ingredient.rows).toBe(4);
        expect(ingredient.target).toEqual([1, 2]);
        expect(ingredient.defaultIndex).toBe(3);
        expect(ingredient.maxLength).toBe(12);
        expect(ingredient.toggleValues).toEqual(["Hex", "Decimal"]);
        expect(ingredient.min).toBe(-10);
        expect(ingredient.max).toBe(0);
        expect(ingredient.step).toBe(0.5);
    });

    test("only accepts numbers for min and max", () => {
        const {ingredient} = makeIngredient({
            type: "number",
            value: 1,
            min: "3",
            max: null
        });

        expect(ingredient.min).toBe("");
        expect(ingredient.max).toBe("");
    });
});

describe("HTMLIngredient.toHtml text-like ingredients", () => {
