        const {ingredient} = makeIngredient({type: "populateMultiOption", value: [], target: [0, 2]}, {manager});

        const op = document.createElement("div");
        const wrapper = document.createElement("div");
        const select = document.createElement("select");
        const option = document.createElement("option");
        option.setAttribute("populate-value", JSON.stringify(["alpha", "beta"]));
        select.appendChild(option);
        wrapper.appendChild(select);
        op.appendChild(wrapper);

        const inputs = [0, 1, 2].map(() => {
            const input = document.createElement("input");
            input.className = "arg";
            input.value = "initial";
            op.appendChild(input);
            return input;
        });
        document.body.appendChild(op);

        const observedValues = [];
        const listeners = inputs.map((input, i) => {
            const listener = jest.fn(() => observedValues.push([i, inputs[0].value, inputs[2].value]));
            input.addEventListener("change", listener);
            return listener;
        });

        const event = new Event("change", {cancelable: true});
        Object.defineProperty(event, "target", {value: select});
        const preventDefault = jest.spyOn(event, "preventDefault");
        const stopPropagation = jest.spyOn(event, "stopPropagation");

        ingredient.populateMultiOptionChange(event);

        expect(preventDefault).toHaveBeenCalled();
        expect(stopPropagation).toHaveBeenCalled();
        expect(inputs[0].value).toBe("alpha");
        expect(inputs[1].value).toBe("initial");
        expect(inputs[2].value).toBe("beta");
        expect(listeners[1]).not.toHaveBeenCalled();
        expect(listeners[0]).toHaveBeenCalledTimes(1);
        expect(listeners[2]).toHaveBeenCalledTimes(1);
        // All values were assigned before any target's change event fired.
        expect(observedValues).toEqual([[0, "alpha", "beta"], [2, "alpha", "beta"]]);
        expect(manager.recipe.ingChange).toHaveBeenCalledTimes(1);
    });
});

describe("HTMLIngredient.editableOptionClick", () => {
    afterEach(() => {
        document.body.innerHTML = "";
    });

    function buildDom() {
        const group = document.createElement("div");
        group.className = "form-group";
        const input = document.createElement("input");
        input.className = "arg";
        input.value = "initial";
        group.appendChild(input);

        const append = document.createElement("div");
        append.className = "input-group-append";
        const menu = document.createElement("div");
        menu.className = "dropdown-menu editable-option-menu";
        const link = document.createElement("a");
        link.className = "dropdown-item";
        link.setAttribute("value", "chosen");
        menu.appendChild(link);
        append.appendChild(menu);
        group.appendChild(append);
        document.body.appendChild(group);
        return {input, link};
    }

    test("copies the clicked option's value into the input and notifies the recipe", () => {
        const manager = makeManager();
        const {ingredient} = makeIngredient({type: "editableOption", value: [{name: "x", value: "x"}]}, {manager});
        const {input, link} = buildDom();
        const listener = jest.fn();
        input.addEventListener("change", listener);

        const event = new Event("click", {cancelable: true});
        Object.defineProperty(event, "target", {value: link});
        const preventDefault = jest.spyOn(event, "preventDefault");
        const stopPropagation = jest.spyOn(event, "stopPropagation");

        ingredient.editableOptionClick(event);

        expect(preventDefault).toHaveBeenCalled();
        expect(stopPropagation).toHaveBeenCalled();
        expect(input.value).toBe("chosen");
        expect(listener).toHaveBeenCalledTimes(1);
        expect(manager.recipe.ingChange).toHaveBeenCalledTimes(1);
    });
});

describe("HTMLIngredient.argSelectorChange", () => {
    afterEach(() => {
        document.body.innerHTML = "";
    });

    test("shows and hides argument groups according to the selected option", () => {
        const {ingredient} = makeIngredient({type: "argSelector", value: []});

        const operation = document.createElement("div");
        operation.className = "operation";
        const ingredients = document.createElement("div");
        ingredients.className = "ingredients";
        const groups = [0, 1, 2, 3].map(() => {
            const group = document.createElement("div");
            group.className = "form-group";
            ingredients.appendChild(group);
            return group;
        });
        groups[1].classList.add("d-none");
        groups[2].classList.add("d-none");
        groups[3].classList.add("d-none");

        const select = document.createElement("select");
        const option = document.createElement("option");
        option.setAttribute("turnon", JSON.stringify([1, 2]));
        option.setAttribute("turnoff", JSON.stringify([3]));
        select.appendChild(option);
        operation.appendChild(select);
        operation.appendChild(ingredients);
        document.body.appendChild(operation);

        const event = new Event("change", {cancelable: true});
        Object.defineProperty(event, "target", {value: select});
        const preventDefault = jest.spyOn(event, "preventDefault");
        const stopPropagation = jest.spyOn(event, "stopPropagation");

        ingredient.argSelectorChange(event);

        expect(preventDefault).toHaveBeenCalled();
        expect(stopPropagation).toHaveBeenCalled();
        expect(groups[0].classList.contains("d-none")).toBe(false);
        expect(groups[1].classList.contains("d-none")).toBe(false);
        expect(groups[2].classList.contains("d-none")).toBe(false);
        expect(groups[3].classList.contains("d-none")).toBe(true);
    });
});
