import HTMLIngredient from "../../src/web/HTMLIngredient.mjs";

/**
 * Builds a deterministic fake App. Each call to nextIngId() increments a
 * per-test counter so ingredient ids can be asserted exactly.
 */
function makeApp() {
    let next = 0;
    return {
        nextIngId: jest.fn(() => ++next)
    };
}

function makeManager() {
    return {
        addDynamicListener: jest.fn(),
        recipe: {
            ingChange: jest.fn()
        }
    };
}

function makeIngredient(config, overrides = {}) {
    const app = overrides.app || makeApp();
    const manager = overrides.manager || makeManager();
    const ingredient = new HTMLIngredient({
        name: "Arg",
        type: "string",
        value: "",
        ...config
    }, app, manager);
    return {ingredient, app, manager};
}

function parseHtml(html) {
    const container = document.createElement("div");
    container.innerHTML = html;
    return container;
}

describe("HTMLIngredient constructor", () => {
    test("derives id and tab index from the App ingredient counter", () => {
        const app = {nextIngId: jest.fn(() => 7)};
        const ingredient = new HTMLIngredient({name: "A", type: "string", value: "v"}, app, makeManager());

        expect(app.nextIngId).toHaveBeenCalledTimes(1);
        expect(ingredient.ingId).toBe(7);
        expect(ingredient.id).toBe("ing-7");
        expect(ingredient.tabIndex).toBe(9); // Input = 1, Search = 2, then ingredient id
    });

    test("applies documented defaults when optional config is omitted", () => {
        const {ingredient} = makeIngredient({name: "A", type: "string", value: "v"});

        expect(ingredient.name).toBe("A");
        expect(ingredient.type).toBe("string");
        expect(ingredient.value).toBe("v");
        expect(ingredient.disabled).toBe(false);
        expect(ingredient.hint).toBe(false);
        expect(ingredient.rows).toBe(false);
        expect(ingredient.target).toBeUndefined();
        expect(ingredient.defaultIndex).toBe(0);
        expect(ingredient.maxLength).toBeNull();
        expect(ingredient.toggleValues).toBeUndefined();
        expect(ingredient.min).toBe("");
        expect(ingredient.max).toBe("");
        expect(ingredient.step).toBe(1);
    });

    test("preserves explicit config values, including numeric boundaries", () => {
        const {ingredient} = makeIngredient({
            name: "Num",
            type: "number",
            value: 5,
            disabled: true,
            hint: "A hint",
            rows: 4,
            target: [1, 2],
            defaultIndex: 3,
            maxLength: 12,

            maxLength: 12,
            toggleValues: ["Hex", "Decimal"],
            min: -10,
            max: 0,
            step: 0.5
        });

        expect(ingredient.disabled).toBe(true);
        expect(ingredient.hint).toBe("A hint");
        expect(ingredient.rows).toBe(4);
        expect(ingredient.target).toEqual([1, 2]);
        expect(ingredient.defaultIndex).toBe(3);
        expect(ingredient.maxLength).toBe(12);
        expect(ingredient.toggleValues).toEqual(["Hex", "Decimal"]);
        expect(ingredient.min).toBe(-10);
        expect(ingredient.max).toBe(0);
        expect(ingredient.step).toBe(0.5);
    });

    test("only accepts numbers for min and max", () => {
        const {ingredient} = makeIngredient({
            type: "number",
            value: 1,
            min: "3",
            max: null
        });

        expect(ingredient.min).toBe("");
        expect(ingredient.max).toBe("");
    });

    test("treats falsey optional values as absent", () => {
        const {ingredient} = makeIngredient({
            type: "number",
            value: 1,
            disabled: false,
            hint: "",
            rows: 0,
            defaultIndex: 0,
            maxLength: 0,
            step: 0
        });

        expect(ingredient.disabled).toBe(false);
        expect(ingredient.hint).toBe(false);
        expect(ingredient.rows).toBe(false);
        expect(ingredient.maxLength).toBeNull();
        expect(ingredient.step).toBe(1);
    });
});

describe("HTMLIngredient.toHtml text-like ingredients", () => {
    test.each(["string", "binaryString", "byteArray"])(
        "renders a wide text input for type %s",
        (type) => {
            const {ingredient} = makeIngredient({name: "Input", type, value: "hello"});
            const root = parseHtml(ingredient.toHtml());
            const input = root.querySelector("input.arg");

            expect(input).not.toBeNull();
            expect(input.getAttribute("type")).toBe("text");
            expect(input.getAttribute("id")).toBe(ingredient.id);
            expect(input.getAttribute("arg-name")).toBe("Input");
            expect(input.getAttribute("tabindex")).toBe(String(ingredient.tabIndex));
            expect(input.value).toBe("hello");
            expect(input.hasAttribute("disabled")).toBe(false);
            expect(root.querySelector("label").textContent).toBe("Input");
            expect(root.querySelector(".form-group").className).toContain("ing-wide");
        }
    );

    test.each(["shortString", "binaryShortString"])(
        "renders a short text input for type %s",
        (type) => {
            const {ingredient} = makeIngredient({name: "Short", type, value: "abc"});
            const root = parseHtml(ingredient.toHtml());

            expect(root.querySelector(".form-group").className).toContain("ing-short");
            expect(root.querySelector("input.arg").value).toBe("abc");
        }
    );

    test("renders hint, disabled and maxlength attributes when configured", () => {
        const {ingredient} = makeIngredient({
            name: "Limited",
            type: "string",
            value: "x",
            hint: "A helpful hint",
            disabled: true,
            maxLength: 5
        });
        const root = parseHtml(ingredient.toHtml());
        const input = root.querySelector("input.arg");

        expect(input.hasAttribute("disabled")).toBe(true);
        expect(input.getAttribute("maxlength")).toBe("5");

        const group = root.querySelector(".form-group");
        expect(group.getAttribute("data-toggle")).toBe("tooltip");
        expect(group.getAttribute("title")).toBe("A helpful hint");
    });

    test("omits hint markup when no hint is supplied", () => {
        const {ingredient} = makeIngredient({type: "string", value: "x"});
        const root = parseHtml(ingredient.toHtml());
        const group = root.querySelector(".form-group");

        expect(group.hasAttribute("title")).toBe(false);
        expect(group.hasAttribute("data-toggle")).toBe(false);
    });
});

describe("HTMLIngredient.toHtml toggleString", () => {
    test("renders the text input and every toggle value as a dropdown item", () => {
        const {ingredient} = makeIngredient({
            name: "Delimiter",
            type: "toggleString",
            value: ",",
            toggleValues: ["Comma", "Space", "Tab"]
        });
        const root = parseHtml(ingredient.toHtml());

        expect(root.querySelector("input.arg").value).toBe(",");
        const toggleButton = root.querySelector(".dropdown-toggle");
        expect(toggleButton.textContent).toBe("Comma");
        const items = Array.from(root.querySelectorAll(".dropdown-menu.toggle-dropdown .dropdown-item"));
        expect(items.map(i => i.textContent)).toEqual(["Comma", "Space", "Tab"]);
    });
});

describe("HTMLIngredient.toHtml number", () => {
    test("renders numeric bounds, step and value", () => {
        const {ingredient} = makeIngredient({
            name: "Offset",
            type: "number",
            value: 42,
            min: -5,
            max: 100,
            step: 2
        });
        const root = parseHtml(ingredient.toHtml());
        const input = root.querySelector("input.arg");

        expect(input.getAttribute("type")).toBe("number");
        expect(input.getAttribute("min")).toBe("-5");
        expect(input.getAttribute("max")).toBe("100");
        expect(input.getAttribute("step")).toBe("2");
        expect(input.value).toBe("42");
    });

    test("renders empty min and max when they are not numeric", () => {
        const {ingredient} = makeIngredient({type: "number", value: 0});
        const input = parseHtml(ingredient.toHtml()).querySelector("input.arg");

        expect(input.getAttribute("min")).toBe("");
        expect(input.getAttribute("max")).toBe("");
        expect(input.getAttribute("step")).toBe("1");
    });
});

describe("HTMLIngredient.toHtml boolean", () => {
    test("renders a checked checkbox when the value is truthy", () => {
        const {ingredient} = makeIngredient({name: "Flag", type: "boolean", value: true});
        const input = parseHtml(ingredient.toHtml()).querySelector("input.arg");

        expect(input.getAttribute("type")).toBe("checkbox");
        expect(input.checked).toBe(true);
        expect(input.getAttribute("value")).toBe("Flag");
        expect(input.hasAttribute("disabled")).toBe(false);
    });

    test("renders an unchecked, disabled checkbox when value is falsey and disabled is set", () => {
        const {ingredient} = makeIngredient({name: "Flag", type: "boolean", value: false, disabled: true});
        const input = parseHtml(ingredient.toHtml()).querySelector("input.arg");

        expect(input.checked).toBe(false);
        expect(input.hasAttribute("disabled")).toBe(true);
    });
});

describe("HTMLIngredient.toHtml option", () => {
    test("renders options, optgroups and the selected default index", () => {
        const {ingredient} = makeIngredient({
            name: "Mode",
            type: "option",
            value: ["[Main]", "One", "Two", "[/Main]", "Three"],
            defaultIndex: 2
        });
        const root = parseHtml(ingredient.toHtml());
        const select = root.querySelector("select.arg");

        expect(select).not.toBeNull();
        const optgroup = select.querySelector("optgroup");
        expect(optgroup).not.toBeNull();
        expect(optgroup.getAttribute("label")).toBe("Main");
        expect(Array.from(optgroup.querySelectorAll("option")).map(o => o.textContent)).toEqual(["One", "Two"]);

        const allOptions = Array.from(select.querySelectorAll("option"));
        expect(allOptions.map(o => o.textContent)).toEqual(["One", "Two", "Three"]);
        expect(allOptions.filter(o => o.selected).map(o => o.textContent)).toEqual(["Two"]);
    });
});

describe("HTMLIngredient.toHtml populateOption and populateMultiOption", () => {
    test("renders escaped populate values and registers the single-value change handler", () => {
        const {ingredient, manager} = makeIngredient({
            name: "Populate",
            type: "populateOption",
            value: [
                {name: "[Presets]", value: ""},
                {name: "A", value: "a\"b<c"},
                {name: "[/Presets]", value: ""}
            ],
            target: 2
        });
        const root = parseHtml(ingredient.toHtml());
        const select = root.querySelector("select.arg");

        expect(select.getAttribute("data-target")).toBe("2");
        expect(select.classList).toContain("populate-option");
        const options = select.querySelectorAll("option");
